import {memo, useCallback} from 'react'

import {assignProblemInvestigations, openDialog} from '../../../actions'
import {getBuildType} from '../../../selectors'
import type {BuildId, ProblemOccurrenceId} from '../../../types'
import {DialogType, stringifyId} from '../../../types'
import {emptyArray} from '../../../utils/empty'
import {fetchProblemOccurrence} from '../../packages/BuildProblems/BuildProblems.actions'
import {getProblemOccurrencesById} from '../../packages/BuildProblems/BuildProblems.selectors'

import Investigations from './Investigations'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type Props = {
  className?: string
  iconClassName?: string
  buildId: BuildId | null | undefined
  problemOccurrenceId: ProblemOccurrenceId
  isShowOnlyIcon?: boolean
}

function BuildProblemInvestigations(props: Props) {
  const dispatch = useAppDispatch()
  const {className, iconClassName, buildId, problemOccurrenceId, isShowOnlyIcon} = props

  const problemOccurrence = useAppSelector(state =>
    getProblemOccurrencesById(state, problemOccurrenceId),
  )
  const {problem, currentlyInvestigated, build} = problemOccurrence ?? {}
  const {buildTypeId} = build ?? {}
  const {id: problemId} = problem ?? {}

  const {projectId} = useAppSelector(state => getBuildType(state, buildTypeId)) ?? {}

  const investigations = problem?.investigations?.investigation ?? emptyArray

  const onAssignInvestigation = useCallback(
    (presetFix = false) => {
      if (buildId != null && problemId != null) {
        const submitHandler = () => dispatch(fetchProblemOccurrence(problemOccurrenceId))
        dispatch(assignProblemInvestigations(problemId, buildId, presetFix, submitHandler))
      }
    },
    [dispatch, buildId, problemId, problemOccurrenceId],
  )

  const onShowInvestigationHistory = useCallback(() => {
    if (problemOccurrenceId != null) {
      dispatch(openDialog(stringifyId(problemOccurrenceId), DialogType.INVESTIGATION_HISTORY))
    }
  }, [dispatch, problemOccurrenceId])

  return (
    <Investigations
      className={className}
      iconClassName={iconClassName}
      projectId={projectId}
      buildTypeId={buildTypeId}
      investigations={investigations}
      currentlyInvestigated={currentlyInvestigated}
      isShowOnlyIcon={isShowOnlyIcon}
      onAssignInvestigation={onAssignInvestigation}
      onShowInvestigationHistory={onShowInvestigationHistory}
    />
  )
}

export default memo(BuildProblemInvestigations)
