import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/consts'
import List from '@jetbrains/ring-ui-built/components/list/list'
import {memo, useCallback, useContext} from 'react'

import {usePermission} from '../../../../../../hooks/usePermission'
import {DialogType, InvestigationStates, Permission, stringifyId} from '../../../../../../types'
import ArrowPopupMenu from '../../../../../common/ArrowPopupMenu/ArrowPopupMenu'
import {useLinkProps} from '../../../../../common/RouterLink/RouterLink'
import {PipelinesTargetContext} from '../../../../../pages/PipelinesPages/contexts/targetContext'
import {isMuteInvestigateButtonEnabled} from '../../../../../pages/PipelinesPages/utils/featureToggles'
import {getFullBuildLogLinkParams} from '../../../../BuildLog/BuildLog.utils'
import {ErrorTypes} from '../../../BuildProblems.consts'

import type {Props} from './BuildProblemActions.types'

function BuildProblemActions({
  className,
  icon,
  investigationInCurrentScope,
  problemProjectId,
  problemOccurrence,
  assignInvestigationHandler,
  openDialog,
}: Props) {
  const pipelinesTarget = useContext(PipelinesTargetContext)
  const hasPermissionForInvestigation = usePermission(
    Permission.ASSIGN_INVESTIGATION,
    problemProjectId,
  )
  const hasPermissionForManageProblems = usePermission(
    Permission.MANAGE_BUILD_PROBLEMS,
    problemProjectId,
  )
  const isMuteInvestigationEnabled = !pipelinesTarget || isMuteInvestigateButtonEnabled

  const {id, build, currentlyInvestigated, currentlyMuted, logAnchor, type} = problemOccurrence
  const onAssignInvestigation = useCallback(() => {
    assignInvestigationHandler()
  }, [assignInvestigationHandler])
  const onFixInvestigation = useCallback(() => {
    assignInvestigationHandler(true)
  }, [assignInvestigationHandler])
  const onShowInvestigationHistory = useCallback(() => {
    openDialog(stringifyId(id), DialogType.INVESTIGATION_HISTORY)
  }, [id, openDialog])
  const buildLogLinkProps = useLinkProps({
    params: getFullBuildLogLinkParams({
      buildId: build?.id,
      line: logAnchor,
      expandState: [Number(logAnchor)],
      logFilter: 'debug',
    }),
  })

  const elements: ListDataItem[] = []
  if (isMuteInvestigationEnabled) {
    elements.push({
      rgItemType: List.ListProps.Type.ITEM,
      title: '',
      label: 'Show investigation history',
      onClick: onShowInvestigationHistory,
    })
  }

  if (isMuteInvestigationEnabled && hasPermissionForInvestigation) {
    elements.push({
      rgItemType: List.ListProps.Type.ITEM,
      title: '',
      label:
        currentlyInvestigated === true ||
        investigationInCurrentScope?.state === InvestigationStates.FIXED
          ? 'Reassign investigation...'
          : 'Assign investigation...',
      onClick: onAssignInvestigation,
    })

    if (
      isMuteInvestigationEnabled &&
      currentlyInvestigated === true &&
      investigationInCurrentScope?.state !== InvestigationStates.FIXED
    ) {
      elements.push({
        rgItemType: List.ListProps.Type.ITEM,
        title: '',
        label: 'Fix investigation...',
        onClick: onFixInvestigation,
      })
    }
  }

  if (isMuteInvestigationEnabled && hasPermissionForManageProblems) {
    elements.push({
      rgItemType: List.ListProps.Type.ITEM,
      title: '',
      label: currentlyMuted === true ? 'Unmute problem...' : 'Mute problem...',
      onClick: onAssignInvestigation,
    })
  }

  if (build?.id != null && Number(logAnchor) != null && type !== ErrorTypes.TC_USER_PROVIDED) {
    elements.push({
      href: buildLogLinkProps.href,
      onClick: (_, e) => buildLogLinkProps.onClick?.(e as React.MouseEvent<HTMLAnchorElement>),
      label: 'Show in Build Log',
    })
  }

  return <ArrowPopupMenu className={className} elements={elements} icon={icon} />
}

export default memo(BuildProblemActions)
